import{_ as e,c as t,o as r,a2 as i}from"./chunks/framework.CIiVzG-O.js";const c=JSON.parse('{"title":"服務條款","description":"","frontmatter":{},"headers":[],"relativePath":"zh-TW/guide/terms.md","filePath":"zh-TW/guide/terms.md","lastUpdated":1793163976000}'),o={name:"zh-TW/guide/terms.md"};function h(l,a,p,d,n,s){return r(),t("div",null,[...a[0]||(a[0]=[i('<h1 id="服務條款" tabindex="-1">服務條款 <a class="header-anchor" href="#服務條款" aria-label="Permalink to &quot;服務條款&quot;">​</a></h1><p>本條款規範您對 NueZip 的使用。下載、安裝或使用 NueZip，即表示您同意本條款。若您不同意，請勿使用本應用程式。</p><h2 id="授權與使用" tabindex="-1">授權與使用 <a class="header-anchor" href="#授權與使用" aria-label="Permalink to &quot;授權與使用&quot;">​</a></h2><p>NueZip 依各版本隨附的授權條款提供。根據授權條款，您被授予一項有限、非專屬、不可轉讓的授權，得在您的 Mac 上使用本應用程式。</p><h2 id="僅限本機運作" tabindex="-1">僅限本機運作 <a class="header-anchor" href="#僅限本機運作" aria-label="Permalink to &quot;僅限本機運作&quot;">​</a></h2><p>NueZip 是一款完全離線的應用程式。所有壓縮檔操作都在您裝置的本機上執行。任何檔案、中繼資料或個人資料都不會傳輸到外部伺服器。</p><h2 id="購買" tabindex="-1">購買 <a class="header-anchor" href="#購買" aria-label="Permalink to &quot;購買&quot;">​</a></h2><p>完整功能授權可透過 Mac App Store 以一次性購買取得。所有購買皆由 Apple 處理。NueZip 不經手付款資訊。重新安裝時支援購買恢復。</p><h2 id="使用者責任" tabindex="-1">使用者責任 <a class="header-anchor" href="#使用者責任" aria-label="Permalink to &quot;使用者責任&quot;">​</a></h2><ul><li>合法使用 NueZip，並遵守適用規範。</li><li>請勿嘗試違反授權條款來反編譯、逆向工程或修改 App。</li><li>請勿使用 NueZip 規避壓縮檔上的著作權保護措施或 DRM。</li></ul><h2 id="隱私" tabindex="-1">隱私 <a class="header-anchor" href="#隱私" aria-label="Permalink to &quot;隱私&quot;">​</a></h2><p>請參閱<a href="/zh-TW/guide/privacy.html">隱私權政策</a>，以瞭解關於資料處理方式與隱私的資訊。</p><h2 id="無保證" tabindex="-1">無保證 <a class="header-anchor" href="#無保證" aria-label="Permalink to &quot;無保證&quot;">​</a></h2><p>NueZip 以「現狀」提供，不附任何種類的保證。在法令允許的最大範圍內，維護者免除所有保證，無論是明示、默示、法定或其他形式，包括適售性與特定用途適用性的保證。</p><h2 id="責任限制" tabindex="-1">責任限制 <a class="header-anchor" href="#責任限制" aria-label="Permalink to &quot;責任限制&quot;">​</a></h2><p>在法令允許的最大範圍內，維護者不對因您使用本應用程式所產生的任何間接、偶發、特殊、衍生性或懲罰性損害負責。</p><h2 id="終止" tabindex="-1">終止 <a class="header-anchor" href="#終止" aria-label="Permalink to &quot;終止&quot;">​</a></h2><p>若您未能遵守本條款，授予您的權利將自動終止。</p><h2 id="變更" tabindex="-1">變更 <a class="header-anchor" href="#變更" aria-label="Permalink to &quot;變更&quot;">​</a></h2><p>我們可能不時更新本條款。變更後繼續使用即構成接受修訂後的條款。</p><h2 id="聯絡方式" tabindex="-1">聯絡方式 <a class="header-anchor" href="#聯絡方式" aria-label="Permalink to &quot;聯絡方式&quot;">​</a></h2><p>若對本條款有任何疑問，請在專案儲存庫開立 issue： <code>https://github.com/nuezip/nuezip/issues</code></p><p>或來信至：nuezip@w3cub.com</p><p><em>最後更新：2026 年 6 月 14 日</em></p>',24)])])}const m=e(o,[["render",h]]);export{c as __pageData,m as default};
